module edge_detect(
    input clk, 
    input rst_n, 
    input a,
    output reg rise, 
    output reg down
);
// Sequential logic for edge detection
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Initialize the previous state to 0 on reset
        prev_a <= 1'b0;

        // Initialize rise and down outputs to 0 on reset
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        // Detect rising edge: if prev_a was 0 and a is now 1
        if (prev_a == 1'b0 && a == 1'b1) begin
            rise <= 1'b1;  // Set rise output to 1
        end else begin
            rise <= 1'b0;  // Clear rise output otherwise
        end

        // Detect falling edge: if prev_a was 1 and a is now 0
        if (prev_a == 1'b1 && a == 1'b0) begin
            down <= 1'b1;  // Set down output to 1
        end else begin
            down <= 1'b0;  // Clear down output otherwise
        end

        // Update previous state with current a
        prev_a <= a;
    end
end
// Register to store the previous state of input signal 'a'
reg prev_a;
endmodule
